UPDATE wallets
SET balance = balance + #{amount}, update_time = NOW()
WHERE user_id = #{userId}

UPDATE wallets
SET frozen_amount = frozen_amount + #{amount}, update_time = NOW()
WHERE user_id = #{userId}

UPDATE wallets
SET balance = balance + #{amount}, total_income = total_income + #{amount}, update_time = NOW()
WHERE user_id = #{userId}
